function loadData(){
  try{ var raw=localStorage.getItem(STORE_KEY); if(raw) return JSON.parse(raw); }catch(e){}
  var d=seed(); saveData(d); return d;
}
function saveData(d){ try{ localStorage.setItem(STORE_KEY, JSON.stringify(d)); }catch(e){} }
var DATA = loadData();

function naira(n){ return "₦"+Number(n).toLocaleString("en-NG"); }
function uid(p){ return p+"_"+Math.random().toString(36).slice(2,9); }
function esc(s){ return (s==null?"":String(s)); }
function agentOf(id){ return DATA.agents.find(function(a){return a.id===id;}); }
function statusLabel(s){ return {gazetted:"Active Gazetted", pending:"Lease Pending", offer:"Under Offer", verified:"Verified"}[s] || s; }
function statusClass(s){ return {gazetted:"ok", pending:"warn", offer:"warn", verified:"ok"}[s] || "ok"; }

