/* ---------------- navigation (real pages, not hash routing) ---------------- */
/* Every page in this site is its own physical .html file. Clicking any
   [data-nav] element performs a normal browser navigation (location.href)
   to that file — not a single-page hash change. */
function nav(p){
  if(p.indexOf("listings/")===0){ location.href = "listing.html?id=" + encodeURIComponent(p.split("/")[1]); return; }
  if(p==="admin" || p.indexOf("admin/")===0){
    var sub = p.indexOf("admin/")===0 ? p.split("/")[1] : "";
    if(isAdmin()){ location.href = "admin.html" + (sub ? ("?tab="+sub) : ""); }
    else { location.href = "admin-login.html"; }
    return;
  }
  var map = { "": "index.html", "listings": "listings.html", "agents": "agents.html", "contact": "contact.html" };
  location.href = map[p] || (p + ".html");
}

