function footerHtml(){
  return '<footer><div class="wrap">'
  + '<div class="footer-grid">'
  +   '<div class="footer-brand"><h3>The Savemans Shelters &amp; Uncommon Realtors</h3><p>Distinguished private real estate advocacy, title verification, and mandate conveyance for the discerning avenues of Old GRA, Port Harcourt.</p></div>'
  +   '<div><h5>Legal &amp; Cadastral</h5><a data-nav="contact">Port Harcourt Cadastral Records</a><a data-nav="contact">Federal C of O Verification</a><a data-nav="contact">Legal Deeds</a></div>'
  +   '<div><h5>Mandate Divisions</h5><a data-nav="listings">Diplomatic Leases</a><a data-nav="listings">Private Mandates</a><a data-nav="admin">Chambers Sign-In</a></div>'
  + '</div>'
  + '<div class="footer-bottom"><span>&copy; 2026 The Savemans Shelters &amp; Uncommon Realtors. '+ADDR+'. All Rights Reserved. Direct Chambers: '+PHONE_DISPLAY+'.</span><span>Colonial Zoning Disclosures</span></div>'
  + '</div></footer>';
}
function mount(active, innerHtml){
  document.getElementById("app").innerHTML = ticker() + headerHtml(active) + innerHtml + footerHtml();
  document.querySelectorAll("[data-nav]").forEach(function(el){
    el.addEventListener("click", function(e){ e.preventDefault(); document.getElementById("mobile-nav").classList.remove("open"); nav(el.getAttribute("data-nav")); });
  });
  var mt = document.getElementById("menu-toggle");
  if(mt){ mt.addEventListener("click", function(){ document.getElementById("mobile-nav").classList.toggle("open"); }); }
}
function mountBare(inner){ document.getElementById("app").innerHTML = inner; bindNavAll(); }
function bindNavAll(){
  document.querySelectorAll("[data-nav]").forEach(function(el){
    el.addEventListener("click", function(e){ e.preventDefault(); nav(el.getAttribute("data-nav")); });
  });
}

/* ---------------- listing card ---------------- */
function listingCardHtml(l){
  return '<a class="listing-card" data-nav="listings/'+l.id+'">'
  + '<div class="listing-img">'+(IMAGES[l.id.toUpperCase()] ? '<img src="'+IMAGES[l.id.toUpperCase()]+'" alt="'+l.title+'">' : houseArt(l.art))
  +   '<span class="listing-flag '+(l.type==="let"?"let":"")+'">'+(l.type==="sale"?"For sale":"To let")+'</span>'
  +   '<span class="listing-badge">'+l.badge+'</span>'
  + '</div>'
  + '<div class="listing-body">'
  +   '<div class="listing-loc">'+l.area+'</div>'
  +   '<h3>'+l.title+'</h3>'
  +   '<div class="listing-price">'+naira(l.price)+(l.unit?" "+l.unit:"")+'</div>'
  +   '<div class="listing-specs">'+(l.bed?'<span>'+l.bed+' Beds</span>':'')+(l.bath?'<span>'+l.bath+' Baths</span>':'')+'<span>'+l.size+'</span></div>'
  +   '<div class="listing-footer"><span>DEED #'+l.deedRef+'</span><span>Inspect Dossier &rarr;</span></div>'
  + '</div></a>';
}

