  +       '<h1>'+l.title+'</h1><div class="loc">'+l.area+', Port Harcourt, Rivers State, Nigeria</div>'
  +       '<div class="price-block"><div class="lbl">Acquisition Valuation</div><div class="amt">'+naira(l.price)+(l.unit?" "+l.unit:"")+'</div>'+(l.priceWords?'<div style="font-size:.72rem; color:var(--text-soft); font-style:italic; margin-top:4px;">'+l.priceWords+'</div>':'')+'</div>'
  +       '<div class="spec-grid">'+(l.bed?'<div><strong>'+l.bed+' Bedrooms</strong><span>Chambers</span></div>':'')+(l.bath?'<div><strong>'+l.bath+' Bathrooms</strong><span>Sanitary Suites</span></div>':'')+'<div><strong>'+l.size+'</strong><span>Cadastral Plot</span></div><div><strong>'+(l.type==="sale"?"C of O":"Lease")+'</strong><span>Title Type</span></div></div>'
  +       (agent ? '<div class="agent-mini"><div class="role">Managing Partner</div><h4>'+agent.name+'</h4><div class="sub">Principal Mandate Partner · Port Harcourt Chambers</div><a class="btn-dark" style="width:100%; justify-content:center; margin-bottom:10px;" href="'+WA+'" target="_blank" rel="noopener">&#9742; Direct WhatsApp Mandate Inquiry</a><a class="btn-outline" style="width:100%; justify-content:center; display:flex;" data-nav="contact">Request Cadastral Title Inspection</a><p class="quote">"Private compound inspections conducted strictly by appointment for vetted principals and diplomatic attaches."</p></div>' : '')
